Contract.make {
  description "returns item availability"
  request {
    method GET()
    url "/items/42/availability"
  }
  response {
    status OK()
    headers { contentType(applicationJson()) }
    body([
      itemId: 42,
      available: true,
      quantityOnHand: $(anyPositiveInt())
    ])
  }
}
